package br.edu.ifrn.promptuario.modules.clinical.controller;

import br.edu.ifrn.promptuario.modules.clinical.dto.*;
import br.edu.ifrn.promptuario.modules.clinical.event.PrescriptionPdfRequestedEvent;
import br.edu.ifrn.promptuario.modules.clinical.event.CertificatePdfRequestedEvent;
import br.edu.ifrn.promptuario.modules.clinical.model.*;
import br.edu.ifrn.promptuario.modules.clinical.repository.*;
import br.edu.ifrn.promptuario.shared.exception.ResourceNotFoundException;
import br.edu.ifrn.promptuario.shared.event.MedicalRecordCreatedEvent;
import br.edu.ifrn.promptuario.shared.messaging.EventPublisher;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.transaction.Transactional;
import jakarta.validation.Valid;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import br.edu.ifrn.promptuario.shared.storage.S3StorageService;
import br.edu.ifrn.promptuario.modules.patient.service.PatientService;
import br.edu.ifrn.promptuario.shared.exception.ForbiddenException;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@RestController @RequestMapping("/api/v1/records") @Tag(name="Medical records") @Transactional
public class MedicalRecordController {
    private final MedicalRecordRepository records; private final AppointmentRepository appointments; private final PrescriptionRepository prescriptions; private final ExamRequestRepository exams; private final MedicalCertificateRepository certificates; private final EventPublisher eventPublisher; private final ApplicationEventPublisher applicationEventPublisher; private final S3StorageService storage; private final String prescriptionBucket; private final PatientService patients;
    public MedicalRecordController(MedicalRecordRepository records,AppointmentRepository appointments,PrescriptionRepository prescriptions,ExamRequestRepository exams,MedicalCertificateRepository certificates,EventPublisher eventPublisher,ApplicationEventPublisher applicationEventPublisher,S3StorageService storage,@Value("${app.storage.s3.bucket-prescriptions:prescriptions}") String prescriptionBucket,PatientService patients){this.records=records;this.appointments=appointments;this.prescriptions=prescriptions;this.exams=exams;this.certificates=certificates;this.eventPublisher=eventPublisher;this.applicationEventPublisher=applicationEventPublisher;this.storage=storage;this.prescriptionBucket=prescriptionBucket;this.patients=patients;}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('DOCTOR','ADMIN')") @Transactional @Operation(summary="Create SOAP medical record")
    public MedicalRecordResponseDto create(@Valid @RequestBody MedicalRecordCreateDto dto,Authentication auth){MedicalRecord r=dto.toEntity(); r.setAppointment(appointments.findById(dto.appointmentId()).orElseThrow(()->new ResourceNotFoundException("Consulta não encontrada")));r.setDoctorId(auth.getName());MedicalRecord saved=records.save(r);eventPublisher.publish("domain.events","medical_record.created",new MedicalRecordCreatedEvent(UUID.randomUUID(),Instant.now(),"MedicalRecordCreated",UUID.randomUUID().toString(),saved.getId(),saved.getAppointment().getId(),saved.getPatientId(),saved.getDoctorId(),saved.getChiefComplaint(),saved.getDiagnosisCodes(),saved.getPrescriptions().size(),saved.getExamRequests().size()));return MedicalRecordResponseDto.fromEntity(saved);}
    @GetMapping @PreAuthorize("hasAnyRole('ADMIN','DOCTOR','ATTENDANT')") public Map<String,Object> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){var result=records.findAll(org.springframework.data.domain.PageRequest.of(Math.max(page,0),Math.max(size,1)));return Map.of("items",result.getContent().stream().map(MedicalRecordResponseDto::fromEntity).toList(),"total",result.getTotalElements(),"page",result.getNumber(),"size",result.getSize());}
    @GetMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','DOCTOR','ATTENDANT','PATIENT')") public MedicalRecordResponseDto get(@PathVariable String id,Authentication auth){var record=find(id);assertAccess(record.getPatientId(),auth);return MedicalRecordResponseDto.fromEntity(record);}
    @PatchMapping("/{id}") @PreAuthorize("hasAnyRole('DOCTOR','ADMIN')") @Transactional public MedicalRecordResponseDto update(@PathVariable String id,@RequestBody MedicalRecordUpdateDto dto){MedicalRecord r=find(id);if(dto.chiefComplaint()!=null)r.setChiefComplaint(dto.chiefComplaint());if(dto.anamnesis()!=null)r.setAnamnesis(dto.anamnesis());if(dto.physicalExam()!=null)r.setPhysicalExam(dto.physicalExam());if(dto.diagnosis()!=null)r.setDiagnosis(dto.diagnosis());if(dto.diagnosisCodes()!=null)r.setDiagnosisCodes(dto.diagnosisCodes());if(dto.treatmentPlan()!=null)r.setTreatmentPlan(dto.treatmentPlan());if(dto.observations()!=null)r.setObservations(dto.observations());if(dto.richNotes()!=null)r.setRichNotes(dto.richNotes());return MedicalRecordResponseDto.fromEntity(records.save(r));}
    @GetMapping("/patient/{patientId}") @PreAuthorize("hasAnyRole('ADMIN','DOCTOR','ATTENDANT','PATIENT')") public Map<String,Object> history(@PathVariable String patientId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,Authentication auth){assertAccess(patientId,auth);var result=records.findByPatientIdOrderByCreatedAtDesc(patientId,org.springframework.data.domain.PageRequest.of(Math.max(page,0),Math.max(size,1)));return Map.of("items",result.getContent().stream().map(MedicalRecordResponseDto::fromEntity).toList(),"total",result.getTotalElements(),"page",result.getNumber(),"size",result.getSize());}
    @PostMapping("/{recordId}/prescriptions") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('DOCTOR','ADMIN')") @Transactional public PrescriptionResponseDto prescription(@PathVariable String recordId,@Valid @RequestBody PrescriptionCreateDto dto,Authentication auth){MedicalRecord r=find(recordId);Prescription saved=prescriptions.save(dto.toEntity(r,r.getPatientId(),auth.getName()));applicationEventPublisher.publishEvent(new PrescriptionPdfRequestedEvent(saved.getId()));return PrescriptionResponseDto.fromEntity(saved);}
    @GetMapping("/{recordId}/prescriptions") @PreAuthorize("hasAnyRole('ADMIN','DOCTOR','ATTENDANT','PATIENT')") public List<PrescriptionResponseDto> prescriptions(@PathVariable String recordId){find(recordId);return prescriptions.findByRecord_IdOrderByCreatedAtDesc(recordId).stream().map(PrescriptionResponseDto::fromEntity).toList();}
    @GetMapping("/{recordId}/prescriptions/{prescriptionId}/pdf") @PreAuthorize("hasAnyRole('ADMIN','DOCTOR','ATTENDANT','PATIENT')") public Map<String,String> prescriptionPdf(@PathVariable String recordId,@PathVariable String prescriptionId){find(recordId);var prescription=prescriptions.findById(prescriptionId).filter(p->recordId.equals(p.getRecord().getId())).orElseThrow(()->new ResourceNotFoundException("Receita não encontrada"));if(prescription.getPdfS3Key()==null) throw new ResourceNotFoundException("PDF ainda não foi gerado");return Map.of("download_url",storage.generatePresignedDownloadUrl(prescriptionBucket,prescription.getPdfS3Key(),java.time.Duration.ofMinutes(15)).toString());}
    @PostMapping("/{recordId}/exams") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('DOCTOR','ADMIN')") @Transactional public ExamRequestResponseDto exam(@PathVariable String recordId,@Valid @RequestBody ExamRequestCreateDto dto,Authentication auth){MedicalRecord r=find(recordId);ExamRequest e=dto.toEntity(r.getPatientId(),auth.getName());e.setRecord(r);return ExamRequestResponseDto.fromEntity(exams.save(e));}
    @PutMapping("/{recordId}/exams/{examId}/result") @PreAuthorize("hasAnyRole('DOCTOR','ADMIN')") @Transactional public ExamRequestResponseDto result(@PathVariable String recordId,@PathVariable String examId,@Valid @RequestBody ExamResultUpdateDto dto){find(recordId);ExamRequest e=exams.findById(examId).filter(x->recordId.equals(x.getRecord().getId())).orElseThrow(()->new ResourceNotFoundException("Exame não encontrado"));e.setResult(dto.result());e.setResultDate(dto.resultDate()==null?Instant.now():dto.resultDate());return ExamRequestResponseDto.fromEntity(exams.save(e));}
    @PostMapping("/{recordId}/certificates") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('DOCTOR','ADMIN')") @Transactional public MedicalCertificateResponseDto certificate(@PathVariable String recordId,@Valid @RequestBody MedicalCertificateCreateDto dto,Authentication auth){MedicalRecord r=find(recordId);MedicalCertificate c=dto.toEntity(r.getPatientId(),auth.getName());c.setRecord(r);MedicalCertificate saved=certificates.save(c);applicationEventPublisher.publishEvent(new CertificatePdfRequestedEvent(saved.getId()));return MedicalCertificateResponseDto.fromEntity(saved);}
    @GetMapping("/{recordId}/certificates/{certificateId}/pdf") @PreAuthorize("hasAnyRole('ADMIN','DOCTOR','ATTENDANT','PATIENT')") public Map<String,String> certificatePdf(@PathVariable String recordId,@PathVariable String certificateId){find(recordId);var certificate=certificates.findById(certificateId).filter(c->recordId.equals(c.getRecord().getId())).orElseThrow(()->new ResourceNotFoundException("Atestado não encontrado"));if(certificate.getPdfS3Key()==null) throw new ResourceNotFoundException("PDF ainda não foi gerado");return Map.of("download_url",storage.generatePresignedDownloadUrl(prescriptionBucket,certificate.getPdfS3Key(),java.time.Duration.ofMinutes(15)).toString());}
    private MedicalRecord find(String id){return records.findById(id).orElseThrow(()->new ResourceNotFoundException("Prontuário não encontrado"));}
    private void assertAccess(String patientId,Authentication auth){boolean privileged=auth.getAuthorities().stream().anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN")||a.getAuthority().equals("ROLE_DOCTOR")||a.getAuthority().equals("ROLE_ATTENDANT"));if(!privileged&&auth.getAuthorities().stream().anyMatch(a -> a.getAuthority().equals("ROLE_PATIENT"))&&!patientId.equals(patients.getPatientByUserId(auth.getName()).getId()))throw new ForbiddenException("Acesso a dados de outro paciente não permitido");}
}
